command:
// DSCT: Show Observation (test macro)
//
// Select the creature trying to hide. Target the enemies you want judged, or target
// nothing to judge every enemy on the scene.
//
// Each enemy gets a ring: GREEN means the picker would call it observing, BLUE means
// not observing, and the label says why. Amber squares are the ground next to the
// hider that enemy cannot watch, which is the number the suggestion turns on.
//
// With ONE enemy targeted you also get its sight lines, the square where it last saw
// the hider clearly, and the square the hider last attacked it from.
//
// Run it again, or move anything, to clear the overlay.
const api = game.modules.get('draw-steel-combat-tools')?.api;
if (!api?.observation) { ui.notifications.error('Draw Steel: Combat Tools is not active.'); return; }

if (window._dsctObsLayer && !window._dsctObsLayer.destroyed) {
  window._dsctObsLayer.destroy({ children: true });
  window._dsctObsLayer = null;
  return;
}

const hider = canvas.tokens.controlled[0];
if (!hider) { ui.notifications.warn('Select the creature trying to hide.'); return; }
if (!game.combat) ui.notifications.warn('No encounter running, so nothing has been recorded yet.');

let watchers = [...game.user.targets].filter(t => t !== hider && !t.destroyed);
if (!watchers.length) {
  watchers = canvas.tokens.placeables.filter(t =>
    t !== hider && t.actor && t.document.disposition !== hider.document.disposition);
}
if (!watchers.length) { ui.notifications.warn('No enemies found to judge.'); return; }

const GS = canvas.grid.size;
const SEES = 0xd04444;
const HIDES = 0x4a90d9;
const GROUND = 0xe0a020;
const MEMORY = 0x9a6fd0;
const HARM = 0xd07a2a;

const layer = new PIXI.Container();
layer.eventMode = 'none';
canvas.controls.addChild(layer);
window._dsctObsLayer = layer;

const label = (text, x, y, color) => {
  const t = new PIXI.Text(text, new PIXI.TextStyle({
    fontFamily: 'Signika, sans-serif', fontSize: 13, fill: color,
    stroke: 0x000000, strokeThickness: 4, align: 'center',
  }));
  t.anchor.set(0.5, 1);
  t.position.set(x, y);
  layer.addChild(t);
};

const box = (gx, gy, color, alpha, inset = 2) => {
  const g = new PIXI.Graphics();
  g.beginFill(color, alpha);
  g.drawRoundedRect(gx * GS + inset, gy * GS + inset, GS - inset * 2, GS - inset * 2, 4);
  g.endFill();
  layer.addChild(g);
};

const solo = watchers.length === 1;
const lines = [];

for (const watcher of watchers) {
  const v = api.observation.suggest(watcher, hider);
  const color = v.observing ? SEES : HIDES;

  const g = new PIXI.Graphics();
  g.lineStyle(3, color, 0.95);
  g.drawRoundedRect(watcher.x, watcher.y, watcher.w, watcher.h, 6);
  g.beginFill(color, 0.12);
  g.drawRoundedRect(watcher.x, watcher.y, watcher.w, watcher.h, 6);
  g.endFill();
  layer.addChild(g);

  label(`${v.observing ? 'SEES' : 'HIDDEN'} (${v.reason}) ${v.adjacent.obscured}/${v.adjacent.total}`,
    watcher.center.x, watcher.y - 2, color);

  for (const sq of v.near.squares) box(sq.x, sq.y, GROUND, solo ? 0.3 : 0.14);

  if (solo) {
    if (v.lastSeen) {
      box(v.lastSeen.at.x, v.lastSeen.at.y, MEMORY, 0.45, 6);
      label(`last seen clearly${v.lastSeen.round ? ` (rd ${v.lastSeen.round})` : ''}`,
        v.lastSeen.at.x * GS + GS / 2, v.lastSeen.at.y * GS, MEMORY);
    }
    if (v.lastHarm) {
      box(v.lastHarm.at.x, v.lastHarm.at.y, HARM, 0.45, 6);
      label(`attacked from${v.lastHarm.round ? ` (rd ${v.lastHarm.round})` : ''}`,
        v.lastHarm.at.x * GS + GS / 2, (v.lastHarm.at.y + 1) * GS + 14, HARM);
    }
    for (const l of api.sightLines(watcher, hider)) {
      const lg = new PIXI.Graphics();
      lg.lineStyle(1.5, l.blocked ? SEES : 0x44d07a, l.blocked ? 0.25 : 0.7);
      lg.moveTo(l.from.x, l.from.y);
      lg.lineTo((l.blocked && l.hit) ? l.hit.x : l.to.x, (l.blocked && l.hit) ? l.hit.y : l.to.y);
      layer.addChild(lg);
    }
  }

  lines.push(`<b>${watcher.name}</b>: ${v.observing ? 'observing' : 'not observing'} (${v.reason})`
    + ` &mdash; adjacent unwatched ${v.adjacent.obscured}/${v.adjacent.total},`
    + ` nearby ${v.near.obscured}/${v.near.total}`
    + (v.lastSeen ? `, last seen ${v.lastSeen.clear ? 'now' : `at ${v.lastSeen.at.x},${v.lastSeen.at.y}`}` : ', never seen clearly')
    + (v.lastHarm ? `, attacked it in round ${v.lastHarm.round}` : ''));
}

const hg = new PIXI.Graphics();
hg.lineStyle(2, 0xffffff, 0.8);
hg.drawRoundedRect(hider.x, hider.y, hider.w, hider.h, 6);
layer.addChild(hg);

ChatMessage.create({
  whisper: [game.user.id],
  content: `<p><b>Observation of ${hider.name}</b></p><p>${lines.join('<br>')}</p>`
    + `<p style="opacity:.7">Threshold: more than `
    + `${game.settings.get('draw-steel-combat-tools', 'observationAdjacentThreshold')}`
    + ` adjacent unwatched squares suggests hiding.</p>`,
});
